#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);
vector<int>deg(n+1,0);set<pair<int,int>>es;
for(int i=0;i<m;++i){int u,v;scanf("%d %d",&u,&v);
++deg[u];++deg[v];es.insert({min(u,v),max(u,v)});}
int best=0;
for(int i=1;i<=n;++i)for(int j=i+1;j<=n;++j){
int r=deg[i]+deg[j]-(es.count({i,j})?1:0);
best=max(best,r);}
printf("%d\n",best);return 0;}

